SELECT
    IDENTIFICADOR,
    ROWNUM,
    MES,
    CPF_PESSOA,
    MATRICULA,
    NOME_SERVIDOR,
    TAB_INEP,
    TAB_LOTACAO,
    CAST(TAB_CARGA AS integer) TAB_CARGA,
    TIPO_CARGO,
    TIPO_CARGO_DESCRICAO,
    TIPO_CATEGORIA,
    TIPO_CATEGORIA_DESCRICAO,
    TAB_CATEGORIA,
    TAB_CATEGORIA_DESCRICAO,
    TAB_SEGMENTO,
    TAB_SEGMENTO_DESCRICAO,
    REPLACE(TAB_VENCIMENTO, '.', ',') AS VENCIMENTO,
    REPLACE(TAB_VALOR_1, '.', ',') AS TAB_VALOR_1,
    REPLACE(TAB_VALOR_2, '.', ',') AS TAB_VALOR_2,
    REPLACE(TAB_OUTROS, '.', ',') AS TAB_OUTROS,
    REPLACE(TAB_TOTAL, '.', ',') AS TAB_TOTAL,
    ULTIMOS_CAMPOS
FROM
    (
    SELECT
        id_funcionario,
        t2.identificador,
        t2.mes,
        t2.cpf_pessoa,
        t2.matricula,
        t2.nome_servidor,
        t2.tab_inep,
        t2.tab_lotacao,
        t2.tab_carga,
        t2.cargo,
        t2.tipo_cargo,
        t2.tipo_cargo_descricao,
        t2.tipo_categoria,
        t2.tipo_categoria_descricao,
        t2.tab_categoria,
        t2.tab_categoria_descricao,
        t2.tab_segmento,
        t2.tab_segmento_descricao,
        CASE
            WHEN t2.tab_vencimento < 1621 THEN 1621
            ELSE t2.tab_vencimento
        END AS tab_vencimento,
        SUM(
            CASE
                WHEN t2.tab_valor_1 = 0.00 THEN 0.00
                ELSE
                    (
                        CASE
                            WHEN t2.tab_valor_1 < 1621 THEN 1621
                            ELSE t2.tab_valor_1
                        END
                    )
            END ) tab_valor_1,
        SUM(
            CASE
                WHEN t2.tab_valor_2 = 0.00 THEN 0.00
                ELSE
                    (
                        CASE
                            WHEN t2.tab_valor_2 < 1621 THEN 1621
                            ELSE tab_valor_2
                        END
                    )
            END ) tab_valor_2,
        t2.tab_outros,
        SUM(
            CASE
                WHEN t2.tab_total < 1621 THEN 1621
                ELSE tab_total
            END ) tab_total,
        t2.ultimos_campos
    FROM (
        SELECT
            T1.ID_FUNCIONARIO,
            T1.IDENTIFICADOR,
            T1.MES,
            T1.CPF_PESSOA,
            T1.MATRICULA,
            T1.NOME_SERVIDOR,
            T1.TAB_INEP,
            T1.TAB_LOTACAO,
            T1.TAB_CARGA,
            T1.CARGO,
            T1.TIPO_CARGO,
            T1.TIPO_CARGO_DESCRICAO,
            T1.TIPO_CATEGORIA,
            T1.TIPO_CATEGORIA_DESCRICAO,
            T1.TAB_CATEGORIA,
            T1.TAB_CATEGORIA_DESCRICAO,
            T1.TAB_SEGMENTO,
            T1.TAB_SEGMENTO_DESCRICAO,
            CASE WHEN T1.TAB_VENCIMENTO < 1621 THEN 1621 ELSE T1.TAB_VENCIMENTO END AS TAB_VENCIMENTO,
            SUM(T1.TAB_VALOR_1) AS TAB_VALOR_1,
            T1.TAB_VALOR_2,
            T1.TAB_OUTROS,
            SUM(T1.TAB_TOTAL) AS TAB_TOTAL,
            T1.ULTIMOS_CAMPOS
        FROM
            ( WITH TABELA_SEGMENTO AS (SELECT '601330' AS LOTACAO, '22135863' AS INEP, 'U E AMARO ALVES PORTELA' AS NOME_SIOPE, 5 AS SEGMENTO, 'Medio' AS DESC_SEGMENTO FROM DUAL UNION ALL SELECT '602601', '22000054', 'CEJA PROF CONRADO AMORIM DE SOUSA', 8, 'EJA' FROM DUAL UNION ALL SELECT '602301', '22001530', 'U E GERVASIO COSTA', 5, 'Medio' FROM DUAL UNION ALL SELECT '602302', '22001573', 'U E MATIAS OLIMPIO', 4, 'Fundamental 2' FROM DUAL UNION ALL SELECT '602303', '22001603', 'CETI NOSSA SENHORA DA CONCEICAO', 5, 'Medio' FROM DUAL UNION ALL SELECT '602101', '22002391', 'U E DIRCEU ARCOVERDE', 5, 'Medio' FROM DUAL UNION ALL SELECT '610602', '22002391', 'U E DIRCEU ARCOVERDE', 4, 'Fundamental 2' FROM DUAL UNION ALL SELECT '613302', '22002391', 'U E DIRCEU ARCOVERDE', 4, 'Fundamental 2' FROM DUAL UNION ALL SELECT '602305', '22002588', 'U E GAYOSO E ALMENDRA', 5, 'Medio' FROM DUAL UNION ALL SELECT '602102', '22002677', 'U E MARIA MELO', 4, 'Fundamental 2' FROM DUAL UNION ALL SELECT '603301', '22002790', 'U E GOV ALBERTO TAVARES SILVA', 5, 'Medio' FROM DUAL UNION ALL SELECT '603302', '22003100', 'U E MIGUEL ARCOVERDE', 5, 'Medio' FROM DUAL UNION ALL SELECT '602306', '22003452', 'U E VENANCIA LAGES VELOSO', 5, 'Medio' FROM DUAL UNION ALL SELECT '602308', '22004777', 'U E PETRONIO PORTELA', 5, 'Medio' FROM DUAL UNION ALL SELECT '602309', '22004793', 'U E ESTADO DA PARAIBA', 8, 'EJA' FROM DUAL UNION ALL SELECT '602207', '22004815', 'CETI JOSE NOGUEIRA DE AGUIAR', 5, 'Medio' FROM DUAL UNION ALL SELECT '602311', '22004823', 'CEEP LEONARDO DAS DORES', 6, 'Profissional' FROM DUAL UNION ALL SELECT '602312', '22005242', 'U E DOROTEU SERTAO', 5, 'Medio' FROM DUAL UNION ALL SELECT '602209', '22005315', 'U E JOSE MENDES VASCONCELOS', 5, 'Medio' FROM DUAL UNION ALL SELECT '602313', '22006184', 'U E JOAO FRANCISCO', 5, 'Medio' FROM DUAL UNION ALL SELECT '602602', '22006249', 'CEJA JOSE LOPES DE ARAUJO', 8, 'EJA' FROM DUAL UNION ALL SELECT '602314', '22006800', 'U E JOAO DE ASSIS MA